summary:
bash: mkdir -p /tmp/kt && cd /tmp/kt && cat > t.c <<'EOF'
#include <klee/klee.h>
#include <assert.h>
int main(void) {
  int a;
  klee_make_symbolic(&a, sizeof(a), "a");
  if (a == 42) {
    assert(0 && "reached 42");
  }
  return 0;
}
EOF
clang-16 -I/usr/local/include -emit-llvm -c -g -O0 -Xclang -disable-O0-optnone t.c -o t.bc 2>&1 | head -5; echo "cc=$?"; ls -l t.bc; PATH=/usr/local/bin:$PATH klee --libc=none t.bc >/tmp/kt/klee.log 2>&1; echo "klee=$?"; tail -15 /tmp/kt/klee.log

