summary:
bash: cat > /tmp/klee_env.sh <<'EOF'
# --- KLEE installation (LLVM 16 + STP backend, no uClibc) ---
# Kept above the non-interactive guard below so it also applies when .bashrc
# is sourced from a non-interactive shell.
case ":$PATH:" in
  *":/usr/local/bin:"*) ;;
  *) export PATH="/usr/local/bin:$PATH" ;;
esac
case ":$PATH:" in
  *":/usr/lib/llvm-16/bin:"*) ;;
  *) export PATH="/usr/lib/llvm-16/bin:$PATH" ;;
esac
case ":$CPATH:" in
  *":/usr/local/include:"*) ;;
  *) export CPATH="/usr/local/include${CPATH:+:$CPATH}" ;;
esac
export KLEE_INCLUDE_DIR=/usr/local/include
case ":$LD_LIBRARY_PATH:" in
  *":/usr/local/lib:"*) ;;
  *) export LD_LIBRARY_PATH="/usr/local/lib${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}" ;;
esac
# --- end KLEE installation ---

EOF
if grep -q 'KLEE installation (LLVM 16' /root/.bashrc; then echo "already present"; else cat /tmp/klee_env.sh /root/.bashrc > /tmp/bashrc.new && cat /tmp/bashrc.new > /root/.bashrc && echo prepended; fi; sed -n '1,30p' /root/.bashrc

